        "port": {
            "description": "The port what Kanro HTTP server will listen.",
            "type": "number"
        },
        "registry": {
            "description": "The NPM registry what module manager will used.",
            "type": "string"
        },
        "resource": {
            "description": "The static resource dir of app.",
            "type": "string"
        }
    },
    "type": "object"
