                            }
                        },
                        "type": "object"
                    },
                    "type": "array"
                },
                "unpublish_edition": {
                    "items": {
                        "additionalProperties": false,
                        "properties": {
                            "additional_properties": {
                                "$ref": "#/definitions/trait_additional_properties_json"
                            },
                            "operation": {
                                "enum": [
                                    "unpublish_edition"
                                ]
                            },
                            "operation_date": {
