                                        {
                                            "type": "object",
                                            "$ref": "#/definitions/Memcached"
                                        },
                                        {
                                            "type": "object",
                                            "$ref": "#/definitions/Redis"
                                        },
                                        {
                                            "type": "object",
                                            "$ref": "#/definitions/Memory"
                                        }
                                    ]
                                }
                            },
                            "required": [
