            "- only_confirmed_introns: bring back AS events only when their introns are either",
            " present in the primary transcript or in the set of confirmed introns.",
            "- pad: boolean switch. If true, Mikado will pad all the transcript in a gene so that their ends are the same"
          ],
          "required": [
            "report",
            "only_confirmed_introns",
            "pad"
          ],
          "type": "object",
          "properties": {
            "report": {
              "type": "boolean",
              "default": true
            },
            "min_cds_overlap": {
              "type": "number",
              "minimum": 0,
              "maximum": 1,
              "default": 0.5
            },
            "min_cdna_overlap": {
              "type": "number",
              "minimum": 0,
              "maximum": 1,
              "default": 0.6
            },
            "keep_retained_introns": {
              "type": "boolean",
              "default": true
            },
            "keep_cds_disrupted_by_ri": {
              "type": "boolean",
              "default": false
            },
            "max_isoforms": {
              "type": "integer",
              "minimum": 1,
              "default": 10
            },
            "valid_ccodes": {
              "type": "array",
              "items": {
                "type": "string",
                "enum": [
                  "j",
                  "e",
                  "o",
                  "h",
                  "J",
                  "C",
                  "g",
                  "G",
                  "=",
                  "n",
                  "_"
                ]
              },
              "default": [
                "j",
                "J",
                "G",
                "h"
              ]
            },
            "redundant_ccodes": {
              "type": "array",
              "items": {
                "type": "string",
                "enum": [
                  "j",
                  "n",
                  "O",
                  "e",
                  "o",
                  "h",
                  "J",
                  "C",
                  "c",
                  "m",
                  "mo",
                  "=",
                  "_",
                  "x",
                  "p",
                  "P",
                  "X",
                  "I",
                  "i"
                ]
              },
              "default": [
                "c",
                "m",
                "_",
                "=",
                "n"
              ]
            },
            "min_score_perc": {
              "type": "number",
              "default": 0.5,
              "minimum": 0,
              "maximum": 1
            },
            "only_confirmed_introns": {
              "type": "boolean",
              "default": true
            },
            "ts_distance": {
              "type": "integer",
              "default": 2000,
              "minimum": 0
            },
            "pad": {
              "type": "boolean",
              "default": true
            },
            "ts_max_splices": {
              "type": "integer",
              "minimum": 0,
              "default": 2
            }
          }
        },
        "output_format": {
          "Comment": [
            "Parameters related to the output format.",
            "  - source: prefix for the source field in the mikado output.",
            "  - id_prefix: prefix for the ID of the genes/transcripts in the output"
          ],
          "type": "object",
          "properties": {
            "source": {
              "type": "string",
              "default": "Mikado"
            },
            "id_prefix": {
              "type": "string",
              "default": "mikado"
            },
            "report_all_orfs": {
              "type": "boolean",
              "default": false
            }
          }
        },
        "orf_loading": {
          "type": "object",
          "Comment": [
            "Parameters related to ORF loading.",
            "- minimal_secondary_orf_length: Minimum length of a *secondary* ORF to be loaded after the first, in bp. Default: 200 bps",
            "- minimal_orf_length: Minimum length in bps of an ORF to be loaded, as the primary ORF, onto a transcript. Default: 50 bps",
            "- strand_specific: Boolean flag. If set to true, monoexonic transcripts will not have their ORF reversed even if they would have an ORF on the opposite strand."
          ],
          "properties": {
            "minimal_secondary_orf_length": {
              "type": "integer",
              "default": 200,
              "minimum": 0
            },
            "minimal_orf_length": {
              "type": "integer",
              "default": 50,
              "minimum": 0
            },
            "strand_specific": {
              "type": "boolean",
              "default": true
            }
          }
        },
        "chimera_split": {
          "Comment": [
            "Parameters related to the splitting of transcripts in the presence of",
            "two or more ORFs. Parameters:",
            "- execute: whether to split multi-ORF transcripts at all. Boolean.",
            "- blast_check: whether to use BLAST information to take a decision. See blast_params for details.",
            "- blast_params: Parameters related to which BLAST data we want to analyse."
          ],
          "SimpleComment": [
            "Parameters related to the splitting of transcripts in the presence of",
            "two or more ORFs. Parameters:",
            "- execute: whether to split multi-ORF transcripts at all. Boolean.",
            "- blast_check: whether to use BLAST information to take a decision. See blast_params for details.",
            "- blast_params: Parameters related to which BLAST data we want to analyse."
          ],
          "type": "object",
          "properties": {
            "blast_check": {
              "type": "boolean",
              "default": true
            },
            "execute": {
              "type": "boolean",
              "default": true
            },
            "skip": {
              "type": "array",
              "default": []
            },
            "blast_params": {
              "type": "object",
              "Comment": [
                "Parameters for the BLAST check prior to splitting.",
                "- evalue: Minimum evalue for the whole hit. Default: 1e-6",
                "- hsp_evalue: Minimum evalue for any HSP hit (some might be discarded even if the whole hit is valid). Default: 1e-6",
                "- leniency: One of 'STRINGENT', 'LENIENT', 'PERMISSIVE'. Default: STRINGENT",
                "- max_target_seqs: maximum number of hits to consider. Default: 3",
                "- minimal_hsp_overlap: minimum overlap of the ORF with the HSP (*not* reciprocal). Default: 0.8, i.e. 80%",
                "- min_overlap_duplication: minimum overlap (in %) for two ORFs to consider them as target duplications. This means that if two ORFs have no HSPs in common, but the coverage of their disjoint HSPs covers more than this % of the length of the *target*, they represent most probably a duplicated gene."
              ],
              "SimpleComment": [
                "Parameters for the BLAST check prior to splitting.",
                "- evalue: Minimum evalue for the whole hit. Default: 1e-6",
                "- leniency: One of 'STRINGENT', 'LENIENT', 'PERMISSIVE'. Default: STRINGENT",
                "- max_target_seqs: maximum number of hits to consider. Default: 3"
              ],
              "properties": {
                "evalue": {
                  "type": "number",
                  "minimum": 0,
                  "default": 1E-06
                },
                "hsp_evalue": {
                  "type": "number",
                  "minimum": 0,
                  "default": 1E-06
                },
                "leniency": {
                  "type": "string",
                  "enum": [
                    "STRINGENT",
                    "LENIENT",
                    "PERMISSIVE"
                  ],
                  "default": "STRINGENT"
                },
                "max_target_seqs": {
                  "type": "integer",
                  "minimum": 1,
                  "default": 3
                },
                "minimal_hsp_overlap": {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1,
                  "default": 0.5
                },
                "min_overlap_duplication": {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1,
                  "default": 0.8
                }
              }
            }
          },
          "required": [
            "blast_check",
            "execute"
          ]
        },
        "run_options": {
          "type": "object",
          "required": [
            "single_thread"
          ],
          "Comment": [
            "Generic run options.",
            "- shm: boolean flag. If set and the DB is sqlite, it will be copied onto the /dev/shm faux partition",
            "- exclude_cds: boolean flag. If set, the CDS information will not be printed in Mikado output. Default: false",
            "- single_thread: boolean flag. If set, multithreading will be disabled - useful for profiling and debugging."
          ],
          "SimpleComment": [
            "Generic run options.",
            "- intron_range: A range where most of the introns (99%) should fall into. Transcripts with too many",
            " introns larger or smaller than what is defined in this range will be penalised",
            " in the scoring. Default: [60, 900]",
            "- shm: boolean flag. If set and the DB is sqlite, it will be copied onto the /dev/shm faux partition",
            "- single_thread: boolean flag. If set, multithreading will be disabled - useful for profiling and debugging."
          ],
          "properties": {
            "shm": {
              "type": "boolean",
              "default": false
            },
            "exclude_cds": {
              "type": "boolean",
              "default": false
            },
            "intron_range": {
              "type": "array",
              "items": {
                "type": "integer",
                "minimum": 0
              },
              "_uniqueItems": true,
              "maxItems": 2,
              "minItems": 2,
              "default": [
                60,
                10000
              ]
            },
            "only_reference_update": {
              "type": "boolean",
              "default": false
            },
            "check_references": {
              "type": "boolean",
              "default": false
            },
            "single_thread": {
              "type": "boolean",
              "default": false
            }
          }
        },
        "clustering": {
          "type": "object",
          "Comment": [
            "Parameters related to the clustering of transcripts into loci.",
            "- cds_only: boolean, it specifies whether to cluster transcripts only according to their CDS (if present).",
            "- min_cds_overlap: minimal CDS overlap for the second clustering.",
            "- min_cdna_overlap: minimal cDNA overlap for the second clustering.",
            "- flank: maximum distance for transcripts to be clustered within the same superlocus.",
            "- remove_overlapping_fragments: boolean, it specifies whether to remove putative fragments.",
            "- purge: boolean, it specifies whether to remove transcripts which fail the minimum requirements check - or whether to ignore those requirements altogether.",
            "- simple_overlap_for_monoexonic: boolean. If set to true (default), then any overlap mean inclusion in a locus for or against a monoexonic transcript. If set to false, normal controls for the percentage of overlap will apply.",
            "- max_distance_for_fragments: maximum distance from a valid locus for another to be considered a fragment."
          ],
          "SimpleComment": [
            "Parameters related to the clustering of transcripts into loci.",
            "- flank: maximum distance for transcripts to be clustered within the same superlocus."
          ],
          "properties": {
            "cds_only": {
              "type": "boolean",
              "default": false
            },
            "min_cds_overlap": {
              "type": "number",
              "minimum": 1E-06,
              "maximum": 1,
              "default": 0.2
            },
            "min_cdna_overlap": {
              "type": "number",
              "minimum": 1E-06,
              "maximum": 1,
              "default": 0.2
            },
            "purge": {
              "type": "boolean",
              "default": true
            },
            "flank": {
              "type": "integer",
              "minimum": 0,
              "default": 200
            },
            "simple_overlap_for_monoexonic": {
              "type": "boolean",
              "default": true
            }
          }
        },
        "fragments": {
          "type": "object",
          "Comment": [
            "Parameters related to the handling of fragments.",
            "- remove: boolean. Whether to remove fragments or leave them, properly tagged.",
            "- max_distance: maximum distance of a putative fragment from a valid gene.",
            "- valid_class_codes: which class codes will be considered as fragments. Default: (p, P, x, X, i, m, _). Choices: '_' plus any class code with category 'Intronic', 'Fragment', or 'Overlap'."
          ],
          "SimpleComment": [
            "Parameters related to the handling of fragments.",
            "- remove: boolean. Whether to remove fragments or leave them, properly tagged."
          ],
          "properties": {
            "remove": {
              "type": "boolean",
              "default": true
            },
            "max_distance": {
              "type": "number",
              "minimum": 0,
              "default": 2000
            },
            "valid_class_codes": {
              "type": "array",
              "items": {
                "type": "string",
                "enum": [
                  "p",
                  "P",
                  "i",
                  "I",
                  "ri",
                  "rI",
                  "x",
                  "X",
                  "m",
                  "_",
                  "e",
                  "o"
                ]
              },
              "default": [
                "p",
                "P",
                "x",
                "X",
                "i",
                "m",
                "_",
                "e",
                "o"
              ]
            }
          }
        },
        "files": {
          "type": "object",
          "Comment": [
            "Input and output files for Mikado pick.",
            "- gff: input GTF/GFF3 file. Default: mikado_prepared.gtf",
            "- loci_out: output GFF3 file from Mikado pick. Default: mikado.loci.gff3",
            "- subloci_out: optional GFF file with the intermediate subloci. Default: no output",
            "- monoloci_out: optional GFF file with the intermediate monoloci. Default: no output",
            "- log: log file for this step."
          ],
          "SimpleComment": [
            "Input and output files for Mikado pick.",
            "- gff: input GTF/GFF3 file. Default: mikado_prepared.gtf",
            "- loci_out: output GFF3 file from Mikado pick. Default: mikado.loci.gff3",
            "- subloci_out: optional GFF file with the intermediate subloci. Default: no output",
            "- monoloci_out: optional GFF file with the intermediate monoloci. Default: no output",
            "- log: log file for this step."
          ],
          "required": [
            "input"
          ],
          "properties": {
            "output_dir": {
              "type": "string",
              "default": "."
            },
            "input": {
              "type": "string",
              "default": "mikado_prepared.gtf"
            },
            "loci_out": {
              "type": "string",
              "default": "mikado.loci.gff3"
            },
            "subloci_out": {
              "type": [
                "string",
                "null"
              ],
              "default": ""
            },
            "monoloci_out": {
              "type": [
                "string",
                "null"
              ],
              "default": ""
            },
            "log": {
              "type": [
                "string",
                "null"
              ],
              "default": "pick.log"
            }
          }
        }
      }
    },
    "reference": {
      "type": "object",
      "Comment": [
        "Options related to the reference genome.",
        "- genome: the genome FASTA file. Required",
        "- genome_fai: the corresponding FAI for the genome. Inferred if absent.",
        "- transcriptome: a GTF/GFF reference transcriptome. Currently ignored."
      ],
      "required": [
        "genome"
      ],
      "anyOf": [
        {
          "required": [
            "genome"
          ]
        },
        {
          "required": [
            "genome_fai",
            "transcriptome"
          ]
        }
      ],
      "properties": {
        "genome": {
          "type": "string",
          "default": ""
        },
        "genome_fai": {
          "type": [
            "string"
          ],
          "default": ""
        },
        "transcriptome": {
          "type": [
            "string"
          ],
          "default": ""
        }
      }
    }
  }
}

{
    "title": "compile.json Schema",
    "$schema": "http://json-schema.org/draft-07/schema",
    "$id": "https://qooxdoo.org/schema/compile-1-0-0.json",
    "description": "compile.json controls the qx compile command, and while you can use command line parameters to compile an application, most applications will require one.",
    "type": "object",
    "required": [
        "applications",
        "targets",
        "$schema"
    ],
    "additionalProperties": false,
    "properties": {
        "$schema": {
            "type": "string",
            "description": "the json schema of the version of compile.json",
            "enum": [
                "https://qooxdoo.org/schema/compile-1-0-0.json",
                "https://raw.githubusercontent.com/qooxdoo/qooxdoo-compiler/master/source/resource/qx/tool/schema/compile-1-0-0.json"
            ]
        },
        "run": {
            "type": "object",
            "additionalItems": false,
            "required": [
                "application"
            ],
            "properties": {
                "application": {
                    "description": "The name of the application, as specified in the applications[] array",
                    "type": "string"
                },
                "arguments": {
                    "description": "Optional command line arguments",
                    "type": "string"
                }
            }
        },
        "sass": {
            "type": "object",
            "additionalItems": false,
            "properties": {
                "compiler": {
                    "description": "Which SASS compiler to use (default is deprecated \"legacy\" during v6, will default to \"latest\" in v7)",
                    "type": "string",
                    "pattern": "^(legacy|latest)$"
                }
            }
        },
        "applications": {
            "type": "array",
            "description": "Each entry describes an application to be compiled.",
            "minItems": 1,
            "items": {
                "type": "object",
                "additionalItems": false,
                "required": [
                    "class",
                    "name"
                ],
                "properties": {
                    "class": {
                        "description": "The class name of the main application class (it typically inherits from `qx.application.Standalone` for web applications)",
                        "type": "string"
                    },
                    "theme": {
                        "description": "The theme class for the application",
                        "type": "string"
                    },
                    "name": {
                        "description": "An arbitrary, but unique, short name for the application. Should be filename and URL friendly - IE no spaces or special characters",
                        "type": "string"
                    },
                    "title": {
                        "description": "The human readable, customer facing name used to set the <title> tag of the application web page, i.e. in the application's index.html",
                        "type": "string"
                    },
                    "description": {
                        "description": "A description of what the application does. This information is displayed in the package browser.",
                        "type": "string"
                    },
                    "publish": {
                        "description": "Whether this application is to be shown in viewers like qooxdoo's package browser or not (if, e.g., it doesn't work as a standalone demo or is an internal test app which is not for general consumption). Defaults to true.",
                        "type": "boolean",
                        "default": true
                    },
                    "standalone": {
                        "description": "Whether this application can be opened in a browser on its own (true) or is part of a different application (false)",
                        "type": "boolean",
                        "default": true
                    },
                    "environment": {
                        "$ref": "#/properties/environment"
                    },
                    "outputPath": {
                        "description": "The directory to place the application files (e.g. index.js and resource.js), relative to the target output directory",
                        "type": "string"
                    },
                    "bootPath": {
                        "description": "The URI used to access the application directory, i.e. the directory containing index.js and resource.js",
                        "type": "string",
                        "default": "."
                    },
                    "include": {
                        "description": "An array of class names which are to be included in the compilation, regardless of whether the compiler can detect if they are needed (for example, your application dynamically choose class names on the fly). Wildcards are supported by adding a *.",
                        "type": "array",
                        "_uniqueItems": true,
                        "examples": [
                            "qx.util.format.*"
                        ],
                        "items": {
                            "type": "string"
                        }
                    },
                    "exclude": {
                        "description": "An array of class names which are to be excluded from the application, regardless of whether the compiler thinks that they are needed. Wildcards are supported by adding a *. Note that exclude takes priority over include",
                        "type": "array",
                        "_uniqueItems": true,
                        "examples": [
                            "qx.util.format.NumberFormat"
                        ],
                        "items": {
                            "type": "string"
                        }
                    },
                    "type": {
                        "description": "The type of application",
                        "pattern": "^(browser|node|rhino)$",
                        "default": "browser"
                    },
                    "loaderTemplate": {
                        "description": "The boot loader template file, usually determined automatically from the application type",
                        "type": "string"
                    },
                    "default": {
                        "description": "If true, this application is considered the default when serving the application; if not provided then the first browser app is the default application. When applications are generated, each application has it's own directory inside the target directory and also has it's own index.html. However, there is an index.html which is generated in the target output directory that runs the `default` application.",
                        "type": "boolean"
                    },
                    "parts": {
                        "$ref": "#/properties/parts"
                    },
                    "minify": {
                        "$ref": "#/properties/targets"
                    },
                    "save-source-in-map": {
                        "$ref": "#/properties/targets"
                    },
                    "save-unminified": {
                        "$ref": "#/properties/targets"
                    }
                }
            }
        },
        "targets": {
            "type": "array",
            "minItems": 1,
            "items": {
                "type": "object",
                "required": [
                    "type",
                    "outputPath"
                ],
                "additionalProperties": false,
                "properties": {
                    "type": {
                        "description": "Either `source`, `build`, or a class name in qooxdoo-compiler; using a class name is advanced usage, but ultimately the standard names just shortcuts to class names anyway (`source` is `qx.tool.compiler.targets.SourceTarget`, etc)",
                        "type": "string"
                    },
                    "description": {
                        "description": "A description of the target's function.",
                        "type": "string"
                    },
                    "application-types": {
                        "description": "The application types which this target supports",
                        "type": "array",
                        "items": {
                            "type": "string",
                            "pattern": "^(browser|node|rhino)$"
                        }
                    },
                    "application-names": {
                        "description": "The application names which this target supports",
                        "type": "array",
                        "items": {
                            "type": "string"
                        }
                    },
                    "outputPath": {
                        "description": "The folder where the compilation outputs to, and will be created if it does not already exist",
                        "type": "string"
                    },
                    "deployPath": {
                        "description": "The folder where the deploy outputs to.",
                        "type": "string"
                    },
                    "targetClass": {
                        "description": "If you want to use more than the two default target types and/or use custom target classes, you can use the targetClass key to supply the name of the class as a string.",
                        "type": "string"
                    },
                    "bundle": {
                        "$ref": "#/properties/bundle"
                    },
                    "uri": {
                        "description": "this sets the URI used to access the target output directory, i.e. the directory which will contain resources/ and transpiled/",
                        "type": "string"
                    },
                    "environment": {
                        "$ref": "#/properties/environment"
                    },
                    "writeCompileInfo": {
                        "description": "if true, the target will write a compile-info.json and resources.json into the application's output directory, containing the data structures required to generate an application",
                        "type": "boolean"
                    },
                    "typescript": {
                        "type": [
                            "boolean",
                            "string"
                        ],
                        "description": "When true, output the typescript definition into ``./compiled/source/qooxdoo.d.ts`. If you use a string instead of true, the string is the name of the file which is generated inside the target output directory"
                    },
                    "minify": {
                        "description": "Determines the minification to be used for applications, if the target supports it. Can be off, minify, mangle, or beautify. Can be overridden on a per application basis.",
                        "type": "string",
                        "pattern": "^(off|minify|mangle|beautify)$"
                    },
                    "deploy-source-maps": {
                        "description": "If true, the source maps will be deployed.",
                        "type": "boolean"
                    },
                    "save-source-in-map": {
                        "description": "If true, the source file will be saved in the map file if the target supports it. Can be overridden on a per application basis.",
                        "type": "boolean"
                    },
                    "save-unminified": {
                        "description": "If true, the unminified files will be saved if the target supports it. Can be overridden on a per application basis.",
                        "type": "boolean"
                    },
                    "addCreatedAt": {
                        "description": "If true, this will cause every object to have a hidden property called $$createdAt which points to an object containing filename, lineNumber, and column properties.",
                        "type": "boolean"
                    },
                    "babelOptions": {
                        "type": "object",
                        "description": "Options given to @babel/preset-env. With this options the output type of babel can be defined. For details see here: <https://babeljs.io/docs/en/babel-preset-env#options>. They can be overridden per target."
                    },
                    "parts": {
                        "$ref": "#/properties/parts"
                    }
                }
            }
        },
        "defaultTarget": {
            "type": "string",
            "pattern": "^(build|source)$"
        },
        "libraries": {
            "description": "If you don't specify a libraries key, then by default the current directory will be used (provided that there is a Manifest.json file) as a library; this makes sense for most applications.",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "include": {
            "description": "An array of class names which are to be included in the compilation, regardless of whether the compiler can detect if they are needed (for example, your application dynamically choose class names on the fly). Wildcards are supported by adding a *.",
            "type": "array",
            "_uniqueItems": true,
            "examples": [
                "qx.util.format.*"
            ],
            "items": {
                "type": "string"
            }
        },
        "exclude": {
            "description": "An array of class names which are to be excluded from the application, regardless of whether the compiler thinks that they are needed. Wildcards are supported by adding a *. Note that exclude takes priority over include",
            "type": "array",
            "_uniqueItems": true,
            "examples": [
                "qx.util.format.NumberFormat"
            ],
            "items": {
                "type": "string"
            }
